import { create_list_edit_delete_splay_categories } from "@/graphql/mutations";
import { API, graphqlOperation } from "aws-amplify";
import SnackBar from "../SnackBar.vue";
export default {
  props: {
    DialogDeleteCategory: Boolean,
    StoreObj: Object
  },
  components: {
    SnackBar
  },
  data: () => ({
    loading: false,
    SnackBarComponent: {}
  }),
  methods: {
    async DeleteQuestion() {
      this.loading = true;
      try {
        const result = await API.graphql(graphqlOperation(create_list_edit_delete_splay_categories, {
          input: {
            action_type: "DELETE",
            splay_category_id: this.StoreObj.splay_category_id
          }
        }));
        let resultObj = JSON.parse(result.data.create_list_edit_delete_splay_categories);
        if (resultObj && resultObj.Status === "SUCCESS") {
          this.SnackBarComponent = {
            SnackbarVmodel: true,
            SnackbarColor: "green",
            SnackbarText: resultObj.Message
          };
        }
        this.loading = false;
        this.DialogDeleteCategoryEmit(2);
      } catch (error) {
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: "Failed to delete question, try again"
        };
      }
      this.loading = false;
    },
    DialogDeleteCategoryEmit(Toggle) {
      this.$emit("clicked", Toggle);
    }
  }
};
